begin;
create table if not exists public.mme_vendor_onboarding_records(onboarding_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_procurement_vendors(vendor_id),legal_name text not null,tax_classification text,verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected','expired')),verified_by_auth_user_id uuid,verified_at timestamptz,review_notes text,created_at timestamptz not null default now());
create table if not exists public.mme_vendor_documents(vendor_document_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_procurement_vendors(vendor_id),document_type text not null check(document_type in ('w9','insurance','contract','bank_letter','other')),document_name text not null,storage_path text,document_status text not null default 'pending' check(document_status in ('pending','accepted','rejected','expired')),expires_on date,reviewed_by_auth_user_id uuid,reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mme_ap_invoices(ap_invoice_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_procurement_vendors(vendor_id),purchase_order_id uuid references public.mme_purchase_orders(purchase_order_id),vendor_invoice_number text not null,invoice_date date not null,due_date date not null,currency char(3) not null default 'USD',subtotal numeric(16,2) not null check(subtotal>=0),tax_amount numeric(16,2) not null default 0 check(tax_amount>=0),total_amount numeric(16,2) generated always as(subtotal+tax_amount) stored,invoice_status text not null default 'received' check(invoice_status in ('received','under_review','matched','exception','approved','scheduled','partially_paid','paid','void')),match_status text not null default 'not_started' check(match_status in ('not_started','matched','variance','not_required')),discount_due_date date,discount_percent numeric(7,4) check(discount_percent between 0 and 100),discount_amount numeric(16,2) check(discount_amount>=0),source_reference text,created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),unique(vendor_id,vendor_invoice_number),check(due_date>=invoice_date),check(discount_due_date is null or discount_due_date>=invoice_date),check(approved_by_auth_user_id is null or approved_by_auth_user_id<>created_by_auth_user_id));
create table if not exists public.mme_ap_invoice_match_evidence(match_id uuid primary key default gen_random_uuid(),ap_invoice_id uuid not null references public.mme_ap_invoices(ap_invoice_id),purchase_order_id uuid references public.mme_purchase_orders(purchase_order_id),receipt_reference text,invoice_amount numeric(16,2) not null check(invoice_amount>=0),po_amount numeric(16,2),receipt_amount numeric(16,2),variance_amount numeric(16,2),match_result text not null check(match_result in ('matched','variance','not_required')),reviewed_by_auth_user_id uuid not null,review_note text,created_at timestamptz not null default now());
create table if not exists public.mme_ap_payment_schedules(payment_schedule_id uuid primary key default gen_random_uuid(),ap_invoice_id uuid not null references public.mme_ap_invoices(ap_invoice_id),scheduled_date date not null,scheduled_amount numeric(16,2) not null check(scheduled_amount>0),currency char(3) not null default 'USD',payment_method text not null default 'manual' check(payment_method in ('manual','ach','check','wire')),payment_status text not null default 'pending_approval' check(payment_status in ('pending_approval','approved','on_hold','released','paid','cancelled')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,approved_at timestamptz,payment_reference text,paid_at timestamptz,created_at timestamptz not null default now(),check(approved_by_auth_user_id is null or approved_by_auth_user_id<>created_by_auth_user_id));
create table if not exists public.mme_ap_payment_approvals(payment_approval_id uuid primary key default gen_random_uuid(),payment_schedule_id uuid not null references public.mme_ap_payment_schedules(payment_schedule_id),approver_auth_user_id uuid not null,decision text not null check(decision in ('approved','rejected')),decision_note text,decided_at timestamptz not null default now());
create index if not exists mme_ap_invoice_due_idx on public.mme_ap_invoices(due_date,invoice_status);
create index if not exists mme_ap_invoice_vendor_idx on public.mme_ap_invoices(vendor_id,invoice_date desc);
create index if not exists mme_ap_payment_schedule_idx on public.mme_ap_payment_schedules(scheduled_date,payment_status);
create or replace view public.mme_ap_aging as select i.ap_invoice_id,i.vendor_id,v.vendor_name,i.vendor_invoice_number,i.invoice_date,i.due_date,i.currency,i.total_amount,coalesce(sum(case when s.payment_status='paid' then s.scheduled_amount else 0 end),0)::numeric(16,2) as paid_amount,greatest(i.total_amount-coalesce(sum(case when s.payment_status='paid' then s.scheduled_amount else 0 end),0),0)::numeric(16,2) as outstanding_amount,case when i.due_date>=current_date then 'current' when current_date-i.due_date between 1 and 30 then '1-30' when current_date-i.due_date between 31 and 60 then '31-60' when current_date-i.due_date between 61 and 90 then '61-90' else '90+' end as aging_bucket from public.mme_ap_invoices i join public.mme_procurement_vendors v on v.vendor_id=i.vendor_id left join public.mme_ap_payment_schedules s on s.ap_invoice_id=i.ap_invoice_id and s.payment_status='paid' where i.invoice_status not in('void','paid') group by i.ap_invoice_id,v.vendor_name;
create or replace function public.mme_ap_record_match(p_invoice uuid,p_result text,p_actor uuid,p_po_amount numeric,p_receipt_amount numeric,p_receipt_ref text,p_note text) returns uuid language plpgsql security definer set search_path=public as $$declare i public.mme_ap_invoices%rowtype;mid uuid;v numeric;begin if p_result not in('matched','variance','not_required') then raise exception 'invalid_match_result';end if;select * into i from public.mme_ap_invoices where ap_invoice_id=p_invoice for update;if not found or i.invoice_status in('paid','void') then raise exception 'invoice_not_matchable';end if;v:=case when p_result='not_required' then 0 else i.total_amount-coalesce(p_po_amount,0) end;insert into public.mme_ap_invoice_match_evidence(ap_invoice_id,purchase_order_id,receipt_reference,invoice_amount,po_amount,receipt_amount,variance_amount,match_result,reviewed_by_auth_user_id,review_note) values(p_invoice,i.purchase_order_id,p_receipt_ref,i.total_amount,p_po_amount,p_receipt_amount,v,p_result,p_actor,left(coalesce(p_note,''),1000)) returning match_id into mid;update public.mme_ap_invoices set match_status=p_result,invoice_status=case when p_result='matched' then 'matched' when p_result='variance' then 'exception' else 'under_review' end where ap_invoice_id=p_invoice;return mid;end$$;
create or replace function public.mme_ap_approve_invoice(p_invoice uuid,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$declare i public.mme_ap_invoices%rowtype;begin select * into i from public.mme_ap_invoices where ap_invoice_id=p_invoice for update;if not found or i.invoice_status not in('matched','under_review') then raise exception 'invoice_not_approvable';end if;if i.created_by_auth_user_id=p_actor then raise exception 'invoice_self_approval_prohibited';end if;if i.match_status='variance' then raise exception 'invoice_match_exception';end if;update public.mme_ap_invoices set invoice_status='approved',approved_by_auth_user_id=p_actor,approved_at=now() where ap_invoice_id=p_invoice;return p_invoice;end$$;
create or replace function public.mme_ap_approve_payment(p_schedule uuid,p_decision text,p_actor uuid,p_note text) returns uuid language plpgsql security definer set search_path=public as $$declare s public.mme_ap_payment_schedules%rowtype;i public.mme_ap_invoices%rowtype;begin if p_decision not in('approved','rejected') then raise exception 'invalid_payment_decision';end if;select * into s from public.mme_ap_payment_schedules where payment_schedule_id=p_schedule for update;if not found or s.payment_status<>'pending_approval' then raise exception 'payment_not_pending_approval';end if;if s.created_by_auth_user_id=p_actor then raise exception 'payment_self_approval_prohibited';end if;select * into i from public.mme_ap_invoices where ap_invoice_id=s.ap_invoice_id for update;if i.invoice_status not in('approved','scheduled') then raise exception 'invoice_not_approved';end if;insert into public.mme_ap_payment_approvals(payment_schedule_id,approver_auth_user_id,decision,decision_note) values(p_schedule,p_actor,p_decision,left(coalesce(p_note,''),1000));update public.mme_ap_payment_schedules set payment_status=case when p_decision='approved' then 'approved' else 'cancelled' end,approved_by_auth_user_id=case when p_decision='approved' then p_actor end,approved_at=case when p_decision='approved' then now() end where payment_schedule_id=p_schedule;return p_schedule;end$$;
do $$declare t text;begin foreach t in array array['mme_vendor_onboarding_records','mme_vendor_documents','mme_ap_invoices','mme_ap_invoice_match_evidence','mme_ap_payment_schedules','mme_ap_payment_approvals'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on function public.mme_ap_record_match(uuid,text,uuid,numeric,numeric,text,text),public.mme_ap_approve_invoice(uuid,uuid),public.mme_ap_approve_payment(uuid,text,uuid,text) from public,anon,authenticated;
grant execute on function public.mme_ap_record_match(uuid,text,uuid,numeric,numeric,text,text),public.mme_ap_approve_invoice(uuid,uuid),public.mme_ap_approve_payment(uuid,text,uuid,text) to service_role;
commit;